/**
 * Per-day activity detail — requests, sessions, active duration and projects —
 * read from the same transcripts `usage-parser.js` sums tokens from (ADR-074).
 *
 * Definitions (each one measured against real transcripts before it was chosen;
 * see ADR-074 for the numbers):
 *
 *   request       one human turn: a distinct `promptId` on a `type:"user"` line
 *                 that is not a subagent line (`isSidechain`), not injected
 *                 context (`isMeta`), not a tool result, and not generated by
 *                 something other than the person (`origin.kind` other than
 *                 "human", e.g. a task notification). Every tool-result line
 *                 of the turn repeats the same promptId, so it counts once.
 *   API call      one deduplicated model response (message.id|requestId) —
 *                 exactly the unit the token totals are already summed over.
 *   conversation  one Claude Code `sessionId` (one transcript file).
 *   session       one block of continuous activity: every user/assistant line
 *                 of the day, from all conversations and projects merged, in
 *                 time order, split wherever nothing happened for IDLE_GAP_MS.
 *   active time   the sum of each session's last event minus its first. No
 *                 padding: a session of a single event is zero seconds.
 *
 * Project: the name of the git repository the line's `cwd` sits in (nearest
 * ancestor holding `.git`), as spelled on disk. Outside any repository, the
 * folder the conversation started in. A path that no longer exists, or the
 * home directory itself, is OTHER_PROJECT. Only the folder NAME ever leaves
 * this machine, never the path.
 *
 * // req: FR-USAGE-001, FR-USAGE-002, ADR-074
 */

import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

/** Inactivity that ends a session. 99% of in-conversation gaps are under 4.1 min; only ~0.2% exceed 30 (ADR-074). */
export const IDLE_GAP_MS = 30 * 60 * 1000;

/** Where activity with no resolvable project is filed. */
export const OTHER_PROJECT = 'Other';

const MAX_PROJECT_NAME = 100;

function cleanName(name) {
  const trimmed = String(name ?? '').trim().slice(0, MAX_PROJECT_NAME);
  return trimmed || OTHER_PROJECT;
}

function samePath(a, b) {
  return process.platform === 'win32' ? a.toLowerCase() === b.toLowerCase() : a === b;
}

/**
 * cwd → { repo, folder }. `repo` is the git repository's name or null outside
 * one; `folder` is the cwd's own name (null for the home directory or a
 * filesystem root, which name a person or a drive rather than a project).
 * Both null when the path no longer exists. Cached: a transcript repeats the
 * same few cwds thousands of times.
 */
export function createProjectResolver({ home = os.homedir() } = {}) {
  const cache = new Map();
  return (cwd) => {
    if (typeof cwd !== 'string' || !cwd.trim()) return { repo: null, folder: null };
    const key = process.platform === 'win32' ? cwd.toLowerCase() : cwd;
    if (cache.has(key)) return cache.get(key);

    let resolved;
    let real = null;
    try {
      // .native: on Windows this returns each component's real casing, so
      // "d:\claude\x" and "D:\CLAUDE\x" resolve to one project, not two.
      real = fs.realpathSync.native(cwd);
    } catch {
      resolved = { repo: null, folder: null };
    }

    if (real) {
      let repo = null;
      for (let dir = real; ; ) {
        if (fs.existsSync(path.join(dir, '.git'))) {
          repo = cleanName(path.basename(dir));
          break;
        }
        const parent = path.dirname(dir);
        if (parent === dir) break;
        dir = parent;
      }
      const isRoot = path.dirname(real) === real;
      const folder = isRoot || samePath(real, home) ? null : cleanName(path.basename(real));
      resolved = { repo, folder };
    }

    cache.set(key, resolved);
    return resolved;
  };
}

/** Sorted epoch-ms times → [{ start, end }], split wherever a gap exceeds `gapMs`. */
export function groupSessions(times, gapMs = IDLE_GAP_MS) {
  const sorted = [...times].sort((a, b) => a - b);
  const blocks = [];
  for (const t of sorted) {
    const last = blocks[blocks.length - 1];
    if (last && t - last.end <= gapMs) last.end = t;
    else blocks.push({ start: t, end: t });
  }
  return blocks;
}

/** Whole seconds of active time across `blocks`. */
export function activeSeconds(blocks) {
  return Math.round(blocks.reduce((ms, b) => ms + (b.end - b.start), 0) / 1000);
}

function isHumanPrompt(entry) {
  if (entry.type !== 'user' || entry.isSidechain || entry.isMeta || !entry.promptId) return false;
  const kind = entry.origin?.kind;
  if (kind && kind !== 'human') return false;
  const content = entry.message?.content;
  if (typeof content === 'string') return content.trim().length > 0;
  return Array.isArray(content) && content.some((block) => block?.type !== 'tool_result');
}

const iso = (ms) => new Date(ms).toISOString();

/**
 * Collects activity while usage-parser.js walks the transcript lines.
 * `observe` sees every parsed line already known to fall on a wanted day;
 * `projectOf` names the project a line belongs to (usage-parser uses it to
 * file each response's tokens); `build` produces one activity object per day.
 */
export class ActivityCollector {
  constructor({ resolveProject = createProjectResolver(), gapMs = IDLE_GAP_MS } = {}) {
    this.resolveProject = resolveProject;
    this.gapMs = gapMs;
    this.events = new Map(); // day -> [{ t, project, conversation }]
    this.prompts = new Map(); // promptId -> { day, t, project }
    this.seenUuids = new Set();
    this.firstCwd = new Map(); // conversation -> first cwd seen
    this.lastCwd = new Map(); // conversation -> latest cwd seen
  }

  conversationOf(entry) {
    return entry.sessionId ?? entry.session_id ?? null;
  }

  projectOf(entry) {
    const conversation = this.conversationOf(entry);
    let cwd = typeof entry.cwd === 'string' && entry.cwd ? entry.cwd : null;
    if (conversation && cwd) {
      if (!this.firstCwd.has(conversation)) this.firstCwd.set(conversation, cwd);
      this.lastCwd.set(conversation, cwd);
    }
    cwd ??= conversation ? this.lastCwd.get(conversation) ?? null : null;

    const here = this.resolveProject(cwd);
    if (here.repo) return here.repo;
    // Outside a repository a subfolder is not a project of its own: name it
    // after the folder the conversation started in.
    const start = (conversation ? this.firstCwd.get(conversation) : null) ?? cwd;
    const origin = this.resolveProject(start);
    return origin.repo ?? origin.folder ?? OTHER_PROJECT;
  }

  /** Records one line; returns its project (null for a line that is not activity). */
  observe(entry, day) {
    if (entry.type !== 'user' && entry.type !== 'assistant') return null;
    const t = Date.parse(entry.timestamp);
    if (!Number.isFinite(t)) return null;
    const project = this.projectOf(entry);
    // The same line can be logged in more than one file (a resumed or forked
    // conversation); its uuid makes it one event.
    if (entry.uuid) {
      if (this.seenUuids.has(entry.uuid)) return project;
      this.seenUuids.add(entry.uuid);
    }

    const conversation = this.conversationOf(entry);
    if (!this.events.has(day)) this.events.set(day, []);
    this.events.get(day).push({ t, project, conversation });

    if (isHumanPrompt(entry)) {
      const prior = this.prompts.get(entry.promptId);
      if (!prior || t < prior.t) this.prompts.set(entry.promptId, { day, t, project });
    }
    return project;
  }

  /**
   * `tokens` is usage-parser's per-day, per-project token map:
   * day -> project -> { input, output, cache_read, cache_creation, calls }.
   */
  build(tokens = new Map()) {
    const promptsByDay = new Map();
    for (const prompt of this.prompts.values()) {
      if (!promptsByDay.has(prompt.day)) promptsByDay.set(prompt.day, []);
      promptsByDay.get(prompt.day).push(prompt);
    }

    const out = new Map();
    for (const [day, events] of this.events) {
      const prompts = promptsByDay.get(day) ?? [];
      const dayTokens = tokens.get(day) ?? new Map();
      const blocks = groupSessions(events.map((e) => e.t), this.gapMs);

      const projectNames = new Set([...events.map((e) => e.project), ...dayTokens.keys()]);
      const projects = [...projectNames].map((name) => {
        const mine = events.filter((e) => e.project === name);
        const own = groupSessions(mine.map((e) => e.t), this.gapMs);
        const t = dayTokens.get(name) ?? { input: 0, output: 0, cache_read: 0, cache_creation: 0, calls: 0 };
        const times = mine.map((e) => e.t);
        return {
          name,
          requestCount: prompts.filter((p) => p.project === name).length,
          apiCallCount: t.calls,
          conversationCount: new Set(mine.map((e) => e.conversation).filter(Boolean)).size,
          sessionCount: own.length,
          activeSeconds: activeSeconds(own),
          input: Math.round(t.input),
          output: Math.round(t.output),
          cacheRead: Math.round(t.cache_read),
          cacheCreation: Math.round(t.cache_creation),
          firstAt: times.length ? iso(Math.min(...times)) : null,
          lastAt: times.length ? iso(Math.max(...times)) : null,
        };
      });
      projects.sort((a, b) => b.input + b.output - (a.input + a.output) || a.name.localeCompare(b.name));

      const sessions = blocks.map((b) => ({
        startedAt: iso(b.start),
        endedAt: iso(b.end),
        requestCount: prompts.filter((p) => p.t >= b.start && p.t <= b.end).length,
        projects: [...new Set(events.filter((e) => e.t >= b.start && e.t <= b.end).map((e) => e.project))].sort(),
      }));

      out.set(day, {
        requestCount: prompts.length,
        apiCallCount: [...dayTokens.values()].reduce((n, t) => n + t.calls, 0),
        conversationCount: new Set(events.map((e) => e.conversation).filter(Boolean)).size,
        sessionCount: blocks.length,
        activeSeconds: activeSeconds(blocks),
        projects,
        sessions,
      });
    }
    return out;
  }
}
